engine.precDocxParagraphs:
function precDocxParagraphs(xml) {
  var s = String(xml || ""), body = s.slice(Math.max(0, s.indexOf("<w:body")));
  body = body.replace(/<w:txbxContent\b[\s\S]*?<\/w:txbxContent>/g, "").replace(/<w:del\b[^>]*>[\s\S]*?<\/w:del>/g, "")
    .replace(/<w:moveFrom\b[^>]*>[\s\S]*?<\/w:moveFrom>/g, "");
