}

// precClauses(paragraphs) — the agreement cut into clauses: a clause starts at a heading (a heading style, a short
// bold or capitalised line, a list item at level 0–1, or a typed number "7.1" / "Section 7.1" / "ARTICLE 7") and runs to
// the next one. [{ number, heading, text, start, end, level }]; text is the clause's body words (heading out).

engine.precClauses:
function precClauses(paras) {
  var P = paras || [], out = [], cur = null;
  var NUM = /^\s*(?:(article|section|clause)\s+)?((?:\d{1,3}(?:\.\d{1,3})*)|[IVXLC]{1,6}(?![a-z]))(\.?)\s+(.*)$/i;
  function headingWords(rest) {
    var m = /^([A-Z][^.:;]{1,80}?)[.:](?:\s+|$)/.exec(rest);
    return m && m[1].split(/\s+/).length <= 10 && !/\b(shall|will|may|must|is|are|agrees?)\b/i.test(m[1]) ? m[1] : "";
  }
  P.forEach(function (p, i) {
    var t = String(p.text || ""), styled = /^heading\s*\d|^title$/i.test(p.style || ""), m = NUM.exec(t);
    var short = t.length <= 90 && t.split(/\s+/).length <= 12;
    var caps = /[A-Z]{3}/.test(t) && t === t.toUpperCase();
    // Unnumbered (a template read as plain text loses Word's list numbers): a short Title Case run-in label still starts one.
    var hw = m ? "" : headingWords(t), titled = hw && hw.split(/\s+/).length <= 6 && hw.split(/\s+/).every(function (x) { return /^[A-Z(]/.test(x) || /^(of|and|the|to|for|in|on|or|a|an|by|with)$/.test(x); });
    var label = m ? headingWords(m[4]) || (short ? m[4].replace(/[.:]\s*$/, "") : "") : ((p.numbered && p.level <= 1) || titled ? hw : "");
    var isHead = !p.inTable && (styled || (short && (p.bold || caps) && !/[.;]\s*$/.test(t.replace(/^[^.]*\.\s*$/, ""))) || (m && label) || (p.numbered && p.level <= 1 && label) || (titled && label));
    if (isHead) {
      var number = m ? (m[1] ? m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase() + " " : "") + m[2] : "";
      var heading = label || (m ? m[4] : t).replace(/[.:]\s*$/, "");
      var body = m && label ? m[4].slice(m[4].indexOf(label) + label.length).replace(/^[.:]\s*/, "") : (!m && label ? t.slice(label.length).replace(/^[.:]\s*/, "") : "");
      cur = { number: number, heading: heading.slice(0, 120), text: body, start: i, end: i, level: p.level >= 0 ? p.level : (m && m[2].indexOf(".") >= 0 ? m[2].split(".").length - 1 : 0) };
      out.push(cur);
    } else if (cur) { cur.text = (cur.text ? cur.text + " " : "") + t; cur.end = i; }
    else { cur = { number: "", heading: "(opening)", text: t, start: i, end: i, level: 0 }; out.push(cur); }
  });
  return out;
}

// precEntity(preamble) — the other party's kind from the opening words: university, hospital, government, nonprofit,
// company, individual. { type, why } (type "" when the words don't say).

engine.precEntity:
function precEntity(preamble) {
  var s = String(preamble || "");
  var KINDS = [
    ["university", /\buniversit(?:y|é|at|ät)\b|\bcollege\b|\binstitute of technology\b|\bschool of medicine\b|\bboard of (?:regents|trustees)\b|\bpublic (?:educational|research) institution\b/i],
    ["hospital", /\bhospital\b|\bmedical cent(?:er|re)\b|\bhealth system\b|\bclinic\b/i],
    ["government", /\bgovernment\b|\bministry\b|\bdepartment of\b|\bfederal\b|\bstate agency\b|\bmunicipality\b/i],
    ["nonprofit", /\bfoundation\b|\bnon-?profit\b|\bnot-for-profit\b|\bassociation\b/i],
    ["company", /\b(?:inc|llc|l\.l\.c|ltd|limited|gmbh|s\.?a\.?s?|b\.?v|ag|plc|corp(?:oration)?|co\.|company|s\.r\.l|pty|kk)\b/i],
    ["individual", /\ban individual\b|\bresiding at\b|\bsole proprietor\b/i],
  ];
  for (var k = 0; k < KINDS.length; k++) { var m = KINDS[k][1].exec(s); if (m) return { type: KINDS[k][0], why: m[0] }; }
  return { type: "", why: "" };
}

// precDate(paragraphs, coreXml) — when the agreement was made: its own words first ("dated as of", "effective as of",
// "made on"), then the latest signature date, then the file's own dates (docProps/core.xml). { date: "YYYY-MM-DD" | "",
// source: "agreement" | "signature" | "file" | "" }.

engine.precDate:
function precDate(paras, coreXml) {
  var MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
  function iso(y, m, d) {
    y = Number(y); m = Number(m); d = Number(d);
    if (y < 100) y += 2000;
    if (!(y > 1980 && y < 2100 && m >= 1 && m <= 12 && d >= 1 && d <= 31)) return "";
    return y + "-" + (m < 10 ? "0" : "") + m + "-" + (d < 10 ? "0" : "") + d;
  }
  function find(s) {
    var m;
    if ((m = /\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b/i.exec(s))) return iso(m[3], MONTHS[m[1].toLowerCase()], m[2]);
    if ((m = /\b(\d{1,2})(?:st|nd|rd|th)?\s+(?:day of\s+)?(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?,?\s+(\d{4})\b/i.exec(s))) return iso(m[3], MONTHS[m[2].toLowerCase()], m[1]);
    if ((m = /\b(\d{4})-(\d{2})-(\d{2})\b/.exec(s))) return iso(m[1], m[2], m[3]);
    if ((m = /\b(\d{1,2})\/(\d{1,2})\/(\d{2,4})\b/.exec(s))) return iso(m[3], m[1], m[2]);   // US order, as Colgate writes them
    return "";
  }
  var P = paras || [], k, d;
  for (k = 0; k < Math.min(P.length, 15); k++) {
    var t = String(P[k].text || ""), at = t.search(/\b(?:dated|effective|made|entered into)\b[^.]{0,40}?\b(?:as of|on|this)\b/i);
    if (at >= 0 && (d = find(t.slice(at, at + 80)))) return { date: d, source: "agreement" };
  }
  var sig = "";
  for (k = Math.floor(P.length * 0.6); k < P.length; k++) {
    var m = /^\s*Date\s*:\s*(.+)$/i.exec(String(P[k].text || "").split("\t")[0]) || /\tDate\s*:\s*(.+)$/i.exec(String(P[k].text || ""));
    if (m && (d = find(m[1])) && d > sig) sig = d;
  }
  if (sig) return { date: sig, source: "signature" };
  var c = String(coreXml || ""), f = (/<dcterms:modified[^>]*>(\d{4})-(\d{2})-(\d{2})/.exec(c) || /<dcterms:created[^>]*>(\d{4})-(\d{2})-(\d{2})/.exec(c));
  return f ? { date: iso(f[1], f[2], f[3]), source: "file" } : { date: "", source: "" };
}

// precOtherParty(preamble) — the party that isn't Colgate, as the opening names it ("between Colgate-Palmolive Company
// … and Example University, …"): its name, only to count distinct counterparties by a one-way hash (never stored).

engine.precOtherParty:
function precOtherParty(preamble) {
  var s = String(preamble || ""), names = [], m;
  var re = /(?:between|and|by|with|among)\s+((?:the\s+)?[A-Z][\w&.,'’-]*(?:\s+(?:[A-Z][\w&.,'’-]*|of|de|du|la|for|the))*)/g;   // "and" ends a name
  while ((m = re.exec(s))) names.push(m[1].replace(/,?\s+(?:a|an)$/i, "").replace(/[,\s]+$/, ""));
  var other = names.filter(function (n) { return !/colgate|palmolive|hill'?s pet|tom'?s of maine|filorga|elta ?md|pca skin/i.test(n) && n.split(/\s+/).length <= 10; })[0] || "";
  return other.replace(/^the\s+/i, "");
}

// precAgreementType(paragraphs, types) — the agreement's type, title first (the kernel's rule for the open document,
// here for a file): the longest type name or alias in the title, a modifier type (Amendment, Renewal, Termination, SOW)
// winning when named; no title match → the most named type in the first 400 characters. types: agreement_types rows
// ({ id, label, aliases, abbrev, keywords }). { type: id | "", title, source: "title" | "words" | "" }.

engine.precAgreementType:
function precAgreementType(paras, types) {
  var MOD = ["Amendment", "Renewal", "Termination", "Statement of Work"];
  var T = (types || []).filter(function (t) { return t && t.id && String(t.id).charAt(0) !== "_" && !t.pseudo; });
  var title = "";
  for (var k = 0; k < Math.min((paras || []).length, 6) && !title; k++) {
    var s = String(paras[k].text || "").trim();
    if (s && s.length <= 140 && s.split(/\s+/).length <= 16 && (s === s.toUpperCase() || /^title$/i.test(paras[k].style || "") || /agreement|amendment|addendum|contract|statement of work/i.test(s))) title = s;
  }
  function names(t) { return [t.id, t.label, t.abbrev].concat(t.aliases || [], t.keywords || [], t.matchKeywords || []).filter(Boolean).map(function (n) { return String(n).toLowerCase(); }); }
  function inText(txt, n) { return n.length > 2 && new RegExp("(^|[^a-z])" + n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "([^a-z]|$)").test(txt); }
  var low = title.toLowerCase(), hits = [];
  T.forEach(function (t) { var best = names(t).filter(function (n) { return inText(low, n); }).sort(function (a, b) { return b.length - a.length; })[0]; if (best) hits.push({ id: t.id, len: best.length }); });
  if (hits.length) {
    var mod = hits.filter(function (h) { return MOD.indexOf(h.id) >= 0; })[0];
    return { type: mod ? mod.id : hits.sort(function (a, b) { return b.len - a.len; })[0].id, title: title, source: "title" };
  }
  var head = (paras || []).map(function (p) { return p.text; }).join(" ").slice(0, 400).toLowerCase(), best = null, most = 0;
  T.forEach(function (t) { var n = names(t).filter(function (x) { return inText(head, x); }).length; if (n > most) { most = n; best = t.id; } });
  return { type: best || "", title: title, source: best ? "words" : "" };
}

// precPool(records, opts) — the approved pool as counts: per agreement type, its agreements and entity types, and per
// clause how many kept Colgate's standard, changed it or removed it (and clauses they added), with distinct attorneys
// (initials) and counterparties (hashes). Only approved, included agreements and clauses, dated within opts.years
// (10) of opts.today (YYYY-MM-DD); undated ones count. { agreements, byType: { type: { agreements, entities, clauses } } }

engine.precPool:
function precPool(records, opts) {
  opts = opts || {};
  var years = opts.years || 10, today = String(opts.today || "9999-12-31"), cut = (Number(today.slice(0, 4)) - years) + today.slice(4);
  var out = { agreements: 0, byType: {}, general: {} };   // general: the taxonomy's general clauses, across all types
  (records || []).forEach(function (r) {
    if (!r || r.status !== "approved" || r.include === false || (r.date && r.date < cut)) return;
    out.agreements++;
    var ty = out.byType[r.agreementType || "Unknown"] = out.byType[r.agreementType || "Unknown"] || { agreements: 0, entities: {}, clauses: {} };
    ty.agreements++;
    ty.entities[r.entityType || "unknown"] = (ty.entities[r.entityType || "unknown"] || 0) + 1;
    (r.clauses || []).forEach(function (c) {
      if (c.include === false) return;
      var k = c.clauseType || "(untitled)", s = ty.clauses[k] = ty.clauses[k] || { unchanged: 0, changed: 0, removed: 0, added: 0, attorneys: {}, parties: {} };
      s[c.outcome] = (s[c.outcome] || 0) + 1;
      if (r.initials) s.attorneys[r.initials] = 1;
      if (r.partyHash) s.parties[r.partyHash] = 1;
      if (c.general && c.clauseKey) {
        var g = out.general[c.clauseKey] = out.general[c.clauseKey] || { unchanged: 0, changed: 0, removed: 0, added: 0, attorneys: {}, parties: {}, types: {} };
        g[c.outcome] = (g[c.outcome] || 0) + 1;
        if (r.initials) g.attorneys[r.initials] = 1;
        if (r.partyHash) g.parties[r.partyHash] = 1;
        g.types[r.agreementType || "Unknown"] = 1;
      }
    });
  });
  var flat = function (s) { s.attorneys = Object.keys(s.attorneys).length; s.parties = Object.keys(s.parties).length; if (s.types) s.types = Object.keys(s.types).length; };
  Object.keys(out.byType).forEach(function (t) { var cl = out.byType[t].clauses; Object.keys(cl).forEach(function (k) { flat(cl[k]); }); });
  Object.keys(out.general).forEach(function (k) { flat(out.general[k]); });
  return out;
}

// precClauseKey(heading, agreementType) — a clause's place in the shared taxonomy, from its heading's words (synonyms
// included): a general clause pools across agreement types ({ key: "governing_law", general: true }); anything else
// stays with its own type ({ key: "<type>: <heading>", general: false }).

engine.precWords:
function precWords(a, b, keepCase) {
  // Words compared without their trailing punctuation; a stand-alone mark is no word at all.
  function toks(x, asIs) { return (asIs ? String(x || "") : String(x || "").toLowerCase()).replace(/[“”"‘’']/g, "'").replace(/[^\w'$%.,;:()-]+/g, " ").trim().split(/\s+/)
    .map(function (w) { return w.replace(/[.,;:]+$/, ""); }).filter(function (w) { return w && /[\w$%]/.test(w); }); }
  var A = toks(a), B = toks(b), n = A.length, m = B.length, AO = keepCase ? toks(a, true) : A, BO = keepCase ? toks(b, true) : B;
  if (!n && !m) return { same: 1, added: 0, removed: 0, sample: [] };
  if (n * m > 4000000) {   // very long clauses: a bag-of-words estimate
    var bag = {}, both = 0;
    A.forEach(function (w) { bag[w] = (bag[w] || 0) + 1; });
    B.forEach(function (w) { if (bag[w]) { bag[w]--; both++; } });
    return { same: both / Math.max(n, m), added: m - both, removed: n - both, sample: [] };
  }
  var L = []; for (var i = 0; i <= n; i++) { L.push(new Uint16Array(m + 1)); }
  for (i = n - 1; i >= 0; i--) for (var j = m - 1; j >= 0; j--) L[i][j] = A[i] === B[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]);
  var ops = []; i = 0; j = 0;
  while (i < n || j < m) {
    if (i < n && j < m && A[i] === B[j]) { ops.push(["=", A[i], AO[i]]); i++; j++; }
    else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) { ops.push(["del", A[i], AO[i]]); i++; }   // the struck words first
    else { ops.push(["ins", B[j], BO[j]]); j++; }
  }
  // A template's fill-in field (xxfillxx) and the words filling it (up to 12 inserted beside it) are a match, not a change.
  for (i = 0; i < ops.length; i++) {
    if (ops[i][0] !== "del" || ops[i][1] !== "xxfillxx") continue;
    ops[i][0] = "fill";
    for (var a = i + 1, c1 = 0; a < ops.length && ops[a][0] === "ins" && c1 < 12; a++, c1++) ops[a][0] = "fill";
    for (var b2 = i - 1, c2 = 0; b2 >= 0 && ops[b2][0] === "ins" && c2 < 12 && !c1; b2--, c2++) ops[b2][0] = "fill";
  }
  var sample = [], run = null, add = 0, rem = 0, eq = 0;
  // keepCase: a stretch joined to the next of its kind across up to 2 unchanged words, which go in with it ("State of
  // New York", not "State … New York"); the first carries the text, the joined ones "". A filled-in field ends a join
  // (its words may be a name).
  var host = {}, pend = {};
  ops.forEach(function (o) {
    var k = o[0];
    if (k === "=" || k === "fill") {
      eq++; run = null;
      if (keepCase) Object.keys(host).forEach(function (h) { if (!host[h]) return; if (k === "fill" || pend[h].length >= 2) { host[h] = null; pend[h] = []; } else pend[h].push(o[2]); });
      return;
    }
    if (k === "ins") add++; else rem++;
    if (!run || run.k !== k) { run = { k: k, t: o[1] }; sample.push(run); } else if (run.t.length < 80) run.t += " " + o[1];
    if (!keepCase) return;
    var hk = host[k];
    if (!hk) { hk = host[k] = run; hk.o = o[2]; hk.n = 1; pend[k] = []; return; }
    if (run !== hk && run.o == null) run.o = "";
    if (hk.n < 40) { hk.o += (pend[k].length ? " " + pend[k].join(" ") : "") + " " + o[2]; hk.n += pend[k].length + 1; }
    pend[k] = [];
  });
  if (keepCase) sample.forEach(function (r) { delete r.n; });
  return { same: eq / Math.max(eq + add, eq + rem, 1), added: add, removed: rem, sample: sample.slice(0, 6) };
}

// precAlign(template, executed, diff) — Colgate's template clauses against the executed agreement's: each pair by heading
// (and number), else by wording; then each one's outcome. template / executed: precClauses' lists.
// [{ t (template index or -1), d (executed index or -1), heading, outcome: "unchanged" | "changed" | "added" |
// "removed", same (0–1), confidence: "high" | "medium" | "low", added, removed, sample }]

engine.precAlign:
function precAlign(template, executed, diff) {
  var T = template || [], D = executed || [], W = diff;   // diff: precWords (engine functions don't see each other in a bundle)
  function norm(h) { return String(h || "").toLowerCase().replace(/^(?:article|section|clause)\s+[\divxlc.]+\s*/i, "").replace(/[^a-z ]+/g, " ").replace(/\s+/g, " ").trim(); }
  function bag(x) { var o = {}; String(x || "").toLowerCase().split(/[^a-z0-9$%]+/).filter(function (w) { return w.length > 2; }).forEach(function (w) { o[w] = 1; }); return o; }
  function overlap(a, b) { var ka = Object.keys(a), kb = Object.keys(b); if (!ka.length || !kb.length) return 0; var n = ka.filter(function (k) { return b[k]; }).length; return n / Math.max(ka.length, kb.length); }
  var usedD = {}, pairs = [];
