// ─── [PRECEDENT-DIGEST] Step 3: precedents as patterns Respond can send (offline parts, 10-20) ───
// precPartyTerm(preamble, name) — what the agreement calls the other party: "Example University (the “University”)"
// → "University"; "" when the opening doesn't say.

engine.precPartyTerm:
function precPartyTerm(preamble, name) {
  var s = String(preamble || ""), n = String(name || "");
