  return m ? m[1].trim() : "";
}

// precDelta(sample, names) — a changed clause as its delta from Colgate's standard, digested when it's read:
// { kind: "insert" | "delete" | "replace" | "", ins, del, sample, scrubbed: true } — the words added and the words
// struck (each at most 40 words, as written where precWords kept them), and the sample to store. No names: emails,
// web addresses and phone numbers go, and each of names ([{ name, term }]) becomes its defined term, else "the other
// party".

engine.precDelta:
function precDelta(sample, names) {
  function scrub(t) {
    t = String(t || "").replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, "[email]").replace(/\bhttps?:\/\/\S+|\bwww\.\S+/gi, "[web address]")
      .replace(/\+?\(?\d[\d\s().-]{8,}\d/g, function (x) { return x.replace(/\D/g, "").length >= 10 ? "[phone]" : x; });
    (names || []).forEach(function (x) {
