  var I = clip(scrub(ins.join(" … "))), D = clip(scrub(del.join(" … ")));
  return { kind: I && D ? "replace" : I ? "insert" : D ? "delete" : "", ins: I, del: D, scrubbed: true,
    sample: (sample || []).map(function (r) { return { k: r.k, t: scrub(r.t) }; }) };
}

// precPatterns(records, opts) — the approved agreements as patterns, per clause (its taxonomy key: a general clause
// across agreement types, a type's own clause only for opts.type): how Colgate's standard fared and the deltas grouped
// by kind and wording, each with agreements, attorneys and counterparties (counts only — no initials, names or dates),
// its share of the agreements with that clause, and strength (rules: strongAttorneys 3, strongShare 0.7,
// strongCounterparties 2; one attorney or one agreement is SINGLE). An exemplar only from a delta digested without
// names (scrubbed). A clause holding others is an article (isArticle); each clause names its article. opts: { type,
// years (10), today, rules }. { agreements, keys: { key: { key, heading, general, article, isArticle, agreements,
// patterns: [{ kind: "kept" | "insert" | "delete" | "replace" | "removed" | "added", agreements, attorneys,
// counterparties, share, level, exemplar }] } } }

engine.precPatterns:
function precPatterns(records, opts) {
  opts = opts || {};
  var R = opts.rules || {}, SA = R.strongAttorneys || 3, SS = R.strongShare || 0.7, SC = R.strongCounterparties || 2;
  var years = opts.years || 10, today = String(opts.today || "9999-12-31"), cut = (Number(today.slice(0, 4)) - years) + today.slice(4);
  function words(t) { var o = {}; String(t || "").toLowerCase().split(/[^a-z0-9$%]+/).forEach(function (w) { if (w.length > 2) o[w] = 1; }); return o; }
  function overlap(a, b) {
