  (records || []).forEach(function (r) {
    if (!r || r.status !== "approved" || r.include === false || (r.date && r.date < cut)) return;
    n++;
    (r.clauses || []).forEach(function (c) {
      if (!c || c.include === false || !c.clauseKey) return;
      if (!c.general && opts.type && r.agreementType !== opts.type) return;
      var e = keys[c.clauseKey] = keys[c.clauseKey] || { general: !!c.general, headings: {}, recs: {}, groups: [], arts: {} };
      e.headings[c.clauseType || ""] = (e.headings[c.clauseType || ""] || 0) + 1;
      e.recs[r.id] = 1;
      if (c.articleKey && c.articleKey !== c.clauseKey) { e.arts[c.articleKey] = (e.arts[c.articleKey] || 0) + 1; holds[c.articleKey] = 1; }
      var d = c.delta || {}, kind = c.outcome === "unchanged" ? "kept" : c.outcome === "removed" ? "removed" : c.outcome === "added" ? "added"
        : d.kind || (c.added && c.removed ? "replace" : c.added ? "insert" : c.removed ? "delete" : "replace");
      var ex = d.scrubbed ? (kind === "delete" ? d.del : d.ins) || "" : "", w = words(ex), g = null;
      for (var i = 0; i < e.groups.length && !g; i++) {
