      patterns: e.groups.map(function (g) {
        var ag = Object.keys(g.recs).length, at = Object.keys(g.att).length, cp = Object.keys(g.par).length, share = total ? ag / total : 0;
        return { kind: g.kind, agreements: ag, attorneys: at, counterparties: cp, share: Math.round(share * 100) / 100,
          level: at <= 1 || ag <= 1 ? "single" : at >= SA && share >= SS && cp >= SC ? "strong" : "some",
          exemplar: /^(insert|delete|replace)$/.test(g.kind) ? g.ex : "" };
      }).sort(function (a, b) { return b.agreements - a.agreements || b.attorneys - a.attorneys; }) };
  });
  return out;
}

// precPick(index, para, max) — at most max (2) patterns for one paragraph the other side changed: para { key, article,
// kind } (their change: "insert" | "delete" | "replace"; key / article: the index keys its heading and its article's
// heading matched). Only kinds that answer their change, never a SINGLE one; the paragraph's own clause before its
// article's (an article's patterns apply to every clause in it), strong before some, the closer kind, the larger share.
// [{ key, scope: "clause" | "article", heading, of (agreements with that clause), pattern, rank }]

engine.precPick:
function precPick(index, para, max) {
