  var REL = { insert: { kept: 2, insert: 3, replace: 2, added: 1 }, delete: { kept: 2, delete: 3, replace: 2, removed: 3 },
    replace: { kept: 2, replace: 3, insert: 2, delete: 2 } }[p.kind] || {};
