    var e = s[0] && Object.prototype.hasOwnProperty.call(K, s[0]) ? K[s[0]] : null;
    if (!e || (s[1] === "article" && (s[0] === p.key || !e.isArticle))) return;
    (e.patterns || []).forEach(function (pt) {
      if (pt.level === "single" || !REL[pt.kind]) return;
      out.push({ key: e.key, scope: s[1], heading: e.heading, of: e.agreements, pattern: pt,
        rank: (pt.level === "strong" ? 100 : 0) + (s[1] === "clause" ? 10 : 0) + REL[pt.kind] * 2 + pt.share });
    });
