  return (x.scope === "article" ? "article " + x.heading + ": " : "") + what + " (" + pt.attorneys + " attorney" + (pt.attorneys === 1 ? "" : "s") + ", " +
    pt.counterparties + " counterpart" + (pt.counterparties === 1 ? "y" : "ies") + ", " + String(pt.level || "").toUpperCase() + ")";
}

// precBudget(items, cap) — a run's precedent lines held to cap tokens (about 4 characters each, 1500 by default):
// items [{ id, lines: [{ text, rank }] }] (each paragraph's best first); over the cap every paragraph's best line goes
// before any second one, the higher rank first — one each for 50+ changed paragraphs. { lines: { id: [text] }, tokens, dropped }

engine.precBudget:
function precBudget(items, cap) {
  cap = cap || 1500;
  var all = [];
  (items || []).forEach(function (it) { (it.lines || []).forEach(function (l, i) { all.push({ id: it.id, i: i, text: String(l.text || ""), rank: +l.rank || 0 }); }); });
