      onOpen: function (id) { _st.open[id] = !_st.open[id]; _paint(); },
      // The owner knows they took Colgate's clauses: every "changed" one kept as is in one go, then adjusted; or back to what ELI found.
      onBulk: function (id, how) {
        var a = find(id); if (!a || !a.clauses) return;
        a.clauses.forEach(function (c) { if (how === "kept" && c.outcome === "changed") c.outcome = "unchanged"; else if (how === "reset") c.outcome = c.detected || c.outcome; });
        _saveBatch().then(_paint);
      },
      onApprove: _approve, onDiscard: _discard, onExclude: _exclude, onExport: _export, onImport: _import,
      storage: { count: _st.records.length + _st.batch.filter(function (a) { return !a.error; }).length, lastBackup: _st.lastBackup || "" },
      onBack: function () { if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome(); },
    }));
  }
  function _show() {
    _st.error = "";
    Promise.all([
      eli.storage.getAll("agreement_types").then(function (rows) { _st.types = (rows || []).filter(function (t) { return t && t.id && String(t.id).charAt(0) !== "_" && !t.pseudo; }); }).catch(function () {}),
      eli.storage.get("config", RECENT_KEY).then(function (r) { if (r && Array.isArray(r.value) && r.value.length) _st.recent = r.value; }).catch(function () {}),
      eli.storage.get("config", "_precedents_last_backup").then(function (r) { _st.lastBackup = (r && r.value) || ""; }).catch(function () {}),
      _loadRecords(),
    ]).then(_paint);
    _paint();
  }
  // [PRECEDENT-DIGEST] precedents.patterns({ type, today }) → { index, pick, line, budget, keyFor } — Respond's P3
  // source (it loads this tool first, so it needn't preload). Records only, never a file; null for an older engine.
  function _patterns(opts) {
    if (!DIGEST) return Promise.resolve(null);
    opts = opts || {};
    return eli.storage.getAll(STORE).then(function (rows) {
      rows = (rows || []).filter(function (r) { return r && String(r.id || "").indexOf(PREFIX) === 0 && r.kind === "precedent_agreement"; });
      return { index: E.precPatterns(rows, { type: opts.type || "", today: opts.today || new Date().toISOString().slice(0, 10), rules: opts.rules }),
        pick: E.precPick, line: E.precLine, budget: E.precBudget, keyFor: E.precClauseKey };
    }).catch(function () { return null; });
  }
  eli.register({ tile: { app_precedents: _show }, precedents: { patterns: _patterns } });
}

jsonTools.css:
/* Precedents (owner-only admin): light panel, navy header with the gold rule, platinum buttons */
._prc_root { display: flex; flex-direction: column; flex: 1 0 auto; min-height: 100%; background: #f8fafc; font: 500 12px/1.45 'Inter', sans-serif; color: #1e293b; }
._prc_head { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: linear-gradient(135deg, #0d1b2a, #1b263b); border-bottom: 3px solid #c9a227; color: #fff; }
._prc_back { border: 0; background: none; color: #fff; font: 700 15px/1 'Inter', sans-serif; cursor: pointer; padding: 0 4px; }
._prc_title { font: 700 14px/1.2 'Inter', sans-serif; letter-spacing: .02em; }
._prc_tag { margin-left: auto; font: 700 9px/1 'Inter', sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #fbe28a; border: 1px solid #c9a227; padding: 3px 6px; }
._prc_body { padding: 12px; display: flex; flex-direction: column; gap: 12px; }
._prc_intro { color: #475569; }
._prc_drop { padding: 14px; border: 1px dashed #c9a227; background: #fffdf6; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 6px; }
._prc_drop_on { background: #fef3c7; }
._prc_drop_t { font: 700 13px/1.3 'Inter', sans-serif; color: #0d1b2a; }
._prc_drop_s { font-size: 11px; color: #64748b; }
._prc_picks { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
._prc_btn { padding: 7px 14px; font: 700 11px/1 'Inter', sans-serif; letter-spacing: .04em; border: 1px solid #b0bcc6; color: #334155; cursor: pointer; background: linear-gradient(180deg, #ffffff 0%, #e8edf2 100%); }
._prc_btn:hover { border-color: #94a3b8; color: #0f172a; }
._prc_btn:disabled { opacity: .55; cursor: default; }
._prc_primary { border-color: #0d47a1; color: #fff; background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%); }
._prc_primary:hover { color: #fff; }
._prc_link { border: 0; background: none; padding: 0; font: 600 11px/1.3 'Inter', sans-serif; color: #92400e; text-decoration: underline dotted; text-underline-offset: 2px; cursor: pointer; }
._prc_err { padding: 7px 9px; background: #fef2f2; border-left: 3px solid #b42318; color: #7f1d1d; font-size: 11.5px; }
._prc_sec { display: flex; flex-direction: column; gap: 8px; }
._prc_k { font: 700 9.5px/1.3 'Inter', sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #8a6d12; }
._prc_card { padding: 10px 11px; background: #fff; border: 1px solid #e2e8f0; border-top: 2px solid #c9a227; display: flex; flex-direction: column; gap: 7px; }
._prc_card_out { opacity: .55; }
._prc_card_top { display: flex; align-items: center; gap: 8px; min-width: 0; }
._prc_name { flex: 1 1 auto; min-width: 0; font: 700 12.5px/1.3 'Inter', sans-serif; color: #0d1b2a; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
._prc_inc { flex: 0 0 auto; font-size: 11px; color: #334155; }
._prc_grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 10px; }
._prc_f { min-width: 0; }
._prc_fl { font: 700 9px/1.3 'Inter', sans-serif; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 2px; }
._prc_fn { font-size: 10.5px; color: #64748b; }
._prc_sel, ._prc_in { width: 100%; box-sizing: border-box; padding: 4px 6px; font: 500 12px/1.3 'Inter', sans-serif; color: #1e293b; border: 1px solid #cbd5e1; background: #fff; }
._prc_ini { text-transform: uppercase; }
._prc_tmpl { font-size: 11px; color: #475569; }
._prc_sum { display: flex; flex-wrap: wrap; gap: 5px; align-items: center; }
._prc_chip { font: 700 10px/1 'Inter', sans-serif; padding: 4px 6px; border: 1px solid currentColor; }
._prc_unchanged { color: #15803d; }
._prc_changed { color: #8a6d12; }
._prc_removed { color: #b42318; }
._prc_added { color: #1d4ed8; }
._prc_bulk { display: flex; flex-wrap: wrap; gap: 12px; }
._prc_low { font-size: 10.5px; color: #92400e; }
._prc_fold { align-self: flex-start; margin: 6px 0 2px; border: 0; background: none; padding: 0; font: 600 11px/1.3 'Inter', sans-serif; color: #475569; cursor: pointer; }
._prc_fold:hover { color: #0f172a; }
._prc_rows { display: flex; flex-direction: column; border-top: 1px solid #eef2f6; }
._prc_row { display: flex; align-items: flex-start; gap: 7px; padding: 6px 4px; border-bottom: 1px solid #eef2f6; cursor: pointer; }
._prc_row:hover { background: #fffbeb; }
._prc_row_out { opacity: .5; }
._prc_row_m { flex: 1 1 auto; min-width: 0; }
._prc_row_h { font-weight: 600; color: #0f172a; }
._prc_dif { margin-top: 2px; font: 400 11.5px/1.45 Georgia, 'Times New Roman', serif; color: #475569; overflow-wrap: anywhere; }
._prc_del { color: #b42318; }
._prc_ins { color: #1d4ed8; text-decoration: none; border-bottom: 1px solid #93c5fd; }
._prc_row ._prc_sel { width: auto; flex: 0 0 auto; font-size: 11px; }
._prc_conf { flex: 0 0 auto; font: 700 9px/1.6 'Inter', sans-serif; text-transform: uppercase; letter-spacing: .06em; color: #64748b; }
._prc_conf_low { color: #b42318; }
._prc_acts { display: flex; justify-content: flex-end; gap: 8px; }
._prc_pl { display: flex; gap: 8px; justify-content: space-between; font-size: 11.5px; border-top: 1px solid #eef2f6; padding-top: 4px; }
._prc_pl_h { font-weight: 600; color: #0f172a; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
._prc_pl_n { flex: 0 0 auto; color: #475569; }
._prc_pr { display: flex; justify-content: space-between; gap: 8px; font-size: 11.5px; padding: 3px 0; border-bottom: 1px solid #eef2f6; }
._prc_pr_t { color: #334155; }
